@push('scripts')<script>function openGroup(x=null){groupTitle.textContent=x?'Edit Kelompok Material':'Tambah Kelompok Material';groupForm.action=x?@json(url('/kelompok-material'))+'/'+x.id:@json(route('kelompok-material.store'));groupMethod.value=x?'PUT':'POST';groupName.value=x?.nama||'';groupFactor.value=x?.faktor_emisi_kgco2e_per_kg||'';groupVersion.value=x?.versi_faktor_emisi||'';groupDate.value=x?.tanggal_berlaku_faktor_emisi?.substring(0,10)||'';groupSource.value=x?.sumber_faktor_emisi||'';groupNotes.value=x?.catatan_faktor_emisi||'';groupModal.classList.remove('hidden');groupModal.classList.add('flex')}</script>@endpush
